4	/**
5	 * NextGEN Gallery v4.x compatibility spec.
6	 *
7	 * Validates that Imagify's NGG integration loads without fatal errors when
8	 * NextGEN Gallery v4.x is active AND that the Bulk Optimization submenu is
9	 * visible in the NGG sidebar.
10	 *
11	 * The primary fix in PR #1059 removes the stale `class_exists('Mixin')` guard
12	 * from the bootstrap file and adds a defensive check inside `add_mixin()` to
13	 * silently no-op on NGG v4.x.
14	 *
15	 * A follow-up fix adds imagify_get_ngg_parent_menu_slug(), which returns
16	 * 'imagely' on NGG v4.x so the Bulk Optimization submenu is registered under
17	 * the correct top-level menu (NGG v4 changed the slug from 'nextgen-gallery'
18	 * to 'imagely').
19	 *
20	 * Related PR:    #1059  (fix/1020-compatibility-imagify-controls-nextgen)
21	 * Related issue: #1020
22	 *
23	 * IMPORTANT: Tests in this file are skipped when the env var
24	 * `IMAGIFY_NGG_INSTALLED` is not set. In standard CI, NGG is not installed by
25	 * default; set that env var and activate the plugin before running this suite.
26	 *
27	 * When `IMAGIFY_NGG_INSTALLED` IS set (local testing with NGG active):
28	 *   npx @wordpress/env run cli wp plugin install nextgen-gallery --activate
29	 *   IMAGIFY_NGG_INSTALLED=1 npx playwright test specs/ngg-compat.spec.ts
30	 */
31	test.describe( 'NextGEN Gallery v4.x compatibility', () => {
32		test.beforeEach( async ( { page } ) => {
33			test.skip(
34				! process.env.IMAGIFY_NGG_INSTALLED,
35				'IMAGIFY_NGG_INSTALLED is not set — skipping NGG compatibility tests. ' +
36				'Run: npx @wordpress/env run cli wp plugin install nextgen-gallery --activate ' +
37				'then re-run with IMAGIFY_NGG_INSTALLED=1',
38			);
39			await loginAsAdmin( page );
40		} );
41	
42		// -----------------------------------------------------------------------
43		// Smoke — no fatal errors when both plugins are active
44		// -----------------------------------------------------------------------
45	
46		test( 'Imagify settings page loads without fatal errors when NGG is active', async ( { page } ) => {
47			await page.goto( '/wp-admin/options-general.php?page=imagify', { waitUntil: 'domcontentloaded' } );
48	
49			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
50			await expect( page ).toHaveURL( /page=imagify/ );
51		} );
52	
53		test( 'Imagify bulk optimization page loads without fatal errors when NGG is active', async ( { page } ) => {
54			await page.goto( '/wp-admin/upload.php?page=imagify-bulk-optimization', { waitUntil: 'domcontentloaded' } );
55	
56			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
57			await expect( page ).toHaveURL( /page=imagify-bulk-optimization/ );
58		} );
59	
60		test( 'WordPress admin dashboard loads without PHP fatal errors when NGG v4 is active', async ( { page } ) => {
61			await page.goto( '/wp-admin/', { waitUntil: 'domcontentloaded' } );
62	
63			const bodyText = await page.locator( 'body' ).innerText();
64			expect( bodyText ).not.toMatch( /Fatal error/i );
65			expect( bodyText ).not.toMatch( /PHP Fatal/i );
66			expect( bodyText ).not.toMatch( /C_Gallery_Storage/i );
67			expect( bodyText ).not.toMatch( /class Mixin/i );
68		} );
69	
70		// -----------------------------------------------------------------------
71		// Core acceptance criterion — Bulk Optimization submenu in NGG v4 sidebar
72		// -----------------------------------------------------------------------
73	
74		test( 'Bulk Optimization submenu is visible in the NGG v4 Imagely sidebar menu', async ( { page } ) => {
75			// NGG v4 registers its top-level menu under the slug 'imagely'.
76			// Imagify must add its submenu under that same slug so it appears in
77			// the visible sidebar (not under the legacy 'nextgen-gallery' slug).
78			await page.goto( '/wp-admin/admin.php?page=imagely', { waitUntil: 'domcontentloaded' } );
79	
80			// WordPress renders submenus in #adminmenu when the parent is active.
81			const submenuLink = page.locator( '#adminmenu a[href*="page=imagify-ngg-bulk-optimization"]' );
82			await expect( submenuLink ).toBeVisible( { timeout: 10_000 } );
83			await expect( submenuLink ).toContainText( 'Bulk Optimization' );
84		} );
85	
86		test( 'Clicking the Bulk Optimization submenu navigates to the bulk page without errors', async ( { page } ) => {
87			await page.goto( '/wp-admin/admin.php?page=imagely', { waitUntil: 'domcontentloaded' } );
88	
89			const submenuLink = page.locator( '#adminmenu a[href*="page=imagify-ngg-bulk-optimization"]' );
90			await expect( submenuLink ).toBeVisible( { timeout: 10_000 } );
91			await submenuLink.click();
92	
93			await expect( page ).toHaveURL( /page=imagify-ngg-bulk-optimization/, { timeout: 10_000 } );
94			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
95	
96			const bodyText = await page.locator( 'body' ).innerText();
97			expect( bodyText ).not.toMatch( /Fatal error/i );
98		} );
99	
100		// -----------------------------------------------------------------------
101		// Regression guard — NGG v4 gallery admin page
102		// -----------------------------------------------------------------------
103	
104		test( 'NGG v4 gallery admin page loads without PHP fatal error', async ( { page } ) => {
105			await page.goto( '/wp-admin/admin.php?page=imagely', { waitUntil: 'domcontentloaded' } );
106	
107			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
108	
109			const bodyText = await page.locator( 'body' ).innerText();
110			expect( bodyText ).not.toMatch( /Fatal error/i );
111			expect( bodyText ).not.toMatch( /C_Gallery_Storage/i );
112		} );
113	
114		// -----------------------------------------------------------------------
115		// Plugin deactivation / reactivation smoke test
116		// -----------------------------------------------------------------------
117	
118		test( 'Imagify can be deactivated and reactivated cleanly with NGG v4.x active', async ( { page } ) => {
119			await page.goto( '/wp-admin/plugins.php', { waitUntil: 'domcontentloaded' } );
120	
121			// Locate the Imagify row via the checkbox value (most stable selector in WP plugins table).
122			const imagifyRow = page.locator( 'tr:has(input[value*="imagify-plugin"])' );
123	
124			const deactivateLink = imagifyRow.locator( 'a', { hasText: /Deactivate/i } );
125			await expect( deactivateLink ).toBeVisible( { timeout: 10_000 } );
126			await deactivateLink.click();
127			await page.waitForURL( /plugins\.php/, { timeout: 10_000 } );
128	
129			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
130	
131			// Re-activate Imagify.
132			const imagifyRowAfter = page.locator( 'tr:has(input[value*="imagify-plugin"])' );
133			const activateLink = imagifyRowAfter.locator( 'a', { hasText: /^Activate$/i } );
134			await expect( activateLink ).toBeVisible( { timeout: 10_000 } );
135			await activateLink.click();
136			await page.waitForURL( /plugins\.php/, { timeout: 10_000 } );
137	
138			await expect( page.locator( '.wp-die-message, #error-page' ) ).toHaveCount( 0 );
139	
140			// Confirm Imagify is active again.
141			const imagifyRowFinal = page.locator( 'tr:has(input[value*="imagify-plugin"])' );
142			await expect( imagifyRowFinal.locator( 'a', { hasText: /Deactivate/i } ) ).toBeVisible();
143		} );
144	} );
