23	/**
24	 * Get NGG Bulk Optimization screen ID.
25	 * Because WP nonsense, the screen ID depends on the menu title, which is translated. So the screen ID changes depending on the administration locale.
26	 *
27	 * @since  1.6.13
28	 * @author Grégory Viguier
29	 *
30	 * @return string
31	 */
32	function imagify_get_ngg_bulk_screen_id() {
33		global $admin_page_hooks;
34	
35		$ngg_menu_slug = imagify_get_ngg_parent_menu_slug();
36		$ngg_menu_slug = isset( $admin_page_hooks[ $ngg_menu_slug ] ) ? $admin_page_hooks[ $ngg_menu_slug ] : sanitize_title( $ngg_menu_slug );
